-- Answer-first content. Existing editorial approvals remain required.
ALTER TABLE public.landing_pages ADD COLUMN IF NOT EXISTS editorial jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.landing_pages ADD CONSTRAINT landing_editorial_object CHECK (jsonb_typeof(editorial)='object');

UPDATE public.landing_pages SET sections='[{"title":"İlk baskı hangi soruya cevap verecek?","body":"Elde tutuşu görmek için hazırlanan bir gövdeyle elektronik yerleşimini denemek için hazırlanan gövdenin ayrıntıları aynı olmayabilir. Projenizin bir sonraki kararını anlatın: boyut, düğme konumu, kapak erişimi veya bağlantı uyumu. Numune kapsamını bu kararı görünür kılacak şekilde oluşturalım."},{"title":"Tek dosyada kaybolmayan revizyonlar","body":"Alternatif tasarımları ayrı kodlarla paylaşmanız karşılaştırmayı kolaylaştırır. Örneğin iki kapak seçeneğinde yalnızca değişen tırnakları işaretleyin; ortak gövde dosyasını ayrıca belirtin. Denemeden çıkan bulguları onaylanan revizyona bağlayarak sonraki üretimde hangi çizimin esas alınacağını netleştirebiliriz."},{"title":"Ürün ekibinden gereken bilgiler","body":"Hedef dış ölçüyü, kullanılacak bileşenleri ve numuneyi inceleyecek kişinin beklentisini talebe ekleyin. Sunum parçasında görünen yüzeyler öncelikli olabilir; montaj prototipinde karşı parçanın referansları önem kazanır. Malzeme ve yüzey tercihini projenin bu aşamasına göre değerlendirelim."},{"title":"Bir sonraki revizyona veri bırakın","body":"Prototipi test ederken yalnızca “oldu” veya “olmadı” sonucu tutmayın. Hangi yüzeyin temas ettiğini, hangi ölçünün değişmesi gerektiğini ve parçanın hangi kullanımda zorlandığını işaretleyin. Aynı parçanın iki revizyonunu birlikte sipariş edecekseniz dosya adlarını ayrı tutun. Böylece sonraki baskı, önceki denemenin ölçülebilir sonucuna dayanır."}]'::jsonb,editorial='{"answer":"3D baskı, dijital modelinizden fiziksel prototip veya düşük adetli parça üretmek için kullanılır. 3dyanımda’da değerlendirme parçanın neyi doğrulayacağıyla başlar: görünüş, montaj, ergonomi veya işlev. Dosya, adet ve kullanım koşulları birlikte incelenerek malzeme, baskı yönü ve numune kapsamı belirlenir.","takeaways":["Görsel sunum ile çalışan prototipin kabul kriterleri farklıdır.","Fiyatı yalnızca gramaj değil; geometri, hazırlık ve son işlem de etkiler.","Tekrar üretim için dosya revizyonunu ve onaylı numuneyi birlikte kaydedin."],"comparison":{"title":"Hangi prototip, hangi karar için?","columns":["İhtiyaç","Öncelik","Talebe eklenecek bilgi"],"rows":[["Görünüş modeli","Yüzey ve görsel bütünlük","Görünecek yüzeyler ve sunum amacı"],["Montaj prototipi","Eşleşen parçalar ve geçmeler","Kritik ölçüler, karşı parça ve montaj sırası"],["İşlev denemesi","Yük, sıcaklık ve hareket","Çalışma koşulu ve test yöntemi"],["Küçük seri","Onaylı revizyonun tekrarı","Numune onayı ve adet planı"]]},"relatedPaths":["/rehber/prototip-maliyetini-ne-belirler","/rehber/3d-baski-mi-cnc-mi","/3d-modelleme","/cozumler/urun-gelistirme-prototipleri"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/3d-baski' AND status='draft' AND sections='[{"title":"İlk baskı hangi soruya cevap verecek?","body":"Elde tutuşu görmek için hazırlanan bir gövdeyle elektronik yerleşimini denemek için hazırlanan gövdenin ayrıntıları aynı olmayabilir. Projenizin bir sonraki kararını anlatın: boyut, düğme konumu, kapak erişimi veya bağlantı uyumu. Numune kapsamını bu kararı görünür kılacak şekilde oluşturalım."},{"title":"Tek dosyada kaybolmayan revizyonlar","body":"Alternatif tasarımları ayrı kodlarla paylaşmanız karşılaştırmayı kolaylaştırır. Örneğin iki kapak seçeneğinde yalnızca değişen tırnakları işaretleyin; ortak gövde dosyasını ayrıca belirtin. Denemeden çıkan bulguları onaylanan revizyona bağlayarak sonraki üretimde hangi çizimin esas alınacağını netleştirebiliriz."},{"title":"Ürün ekibinden gereken bilgiler","body":"Hedef dış ölçüyü, kullanılacak bileşenleri ve numuneyi inceleyecek kişinin beklentisini talebe ekleyin. Sunum parçasında görünen yüzeyler öncelikli olabilir; montaj prototipinde karşı parçanın referansları önem kazanır. Malzeme ve yüzey tercihini projenin bu aşamasına göre değerlendirelim."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Referans objenin projedeki rolü","body":"Tarama talebine yalnızca objenin fotoğrafını değil, ona bağlı tasarım fikrini de ekleyin. Yeni bir muhafaza mevcut yüzeye oturacaksa temas bölgesini gösterin. Sunum için dijitalleştirilen bir obje söz konusuysa görünmesi gereken yüzeyleri ve kullanım ölçeğini açıklayın."},{"title":"Yüzey verisinden tasarım girdisine","body":"Elde edilen yüzeyin doğrudan görüntülenmesi ile düzenlenebilir bir tasarım referansına dönüştürülmesi ayrı işlemlerdir. Dosyayı hangi yazılımda ve hangi amaçla kullanacağınızı baştan bilmek teslim biçimini belirlemeye yardımcı olur. CAD yeniden çizimi gerekiyorsa bunu tarama talebinde belirtin."},{"title":"Objeyi paylaşmadan önce","body":"Yaklaşık boyut, malzeme görünümü ve hareketli parçaların durumunu not edin. Sökülebilen kapaklar veya gizli yüzeyler varsa fotoğraflarda işaretleyin. Fiziksel gönderimden önce değerlendirme kapsamı ve numunenin geri dönüş şekli görüşülmelidir."},{"title":"Taramadan önce çıktı üzerinde anlaşın","body":"Nesnenin bütününü mü, montaja oturan belirli bir yüzeyini mi istediğinizi belirtin. Fotoğrafa bir cetvel eklemek ilk kapsam değerlendirmesine yardımcı olur; bu fotoğraf ölçüm raporu yerine geçmez. Renkli görünüm, geometrik ağ, CAD dosyası ve teknik rapor aynı teslim değildir. Beklenen dosya biçimi ve sonradan düzenleme ihtiyacını teklif aşamasında ayırın."}]'::jsonb,editorial='{"answer":"3D tarama, elinizdeki nesnenin erişilebilen yüzeylerini dijital geometriye dönüştürür. Görsel arşiv, ölçü incelemesi ve yeniden tasarım farklı çıktılar gerektirir. Parçayı tekrar ürettirmek istiyorsanız tarama verisinin yanında düzenlenebilir CAD modeline ihtiyaç olup olmadığını başlangıçta belirlemek gerekir.","takeaways":["Parçanın büyüklüğünü ve yüzey özelliklerini fotoğraflarla gösterin.","Tarama ağı ile parametrik CAD modeli ayrı teslim kalemleridir.","Erişilemeyen iç yüzeyler için ek ölçüm veya söküm gerekebilir."],"comparison":{"title":"Tarama çıktısını kullanım amacına göre seçin","columns":["Amaç","Çıktı","Kontrol"],"rows":[["Dijital arşiv","Yüzey ağı","Eksik yüzey ve geometri temizliği"],["Yeniden tasarım","Referans ağ ve CAD çalışması","Kritik ölçüler ve tasarım niyeti"],["Mevcut modele kıyas","Hizalanmış veri","Referans sistemi ve karşılaştırma kapsamı"]]},"relatedPaths":["/3d-modelleme","/rehber/tarama-ve-tersine-muhendislik","/cozumler/urun-gelistirme-prototipleri"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/3d-tarama' AND status='draft' AND sections='[{"title":"Referans objenin projedeki rolü","body":"Tarama talebine yalnızca objenin fotoğrafını değil, ona bağlı tasarım fikrini de ekleyin. Yeni bir muhafaza mevcut yüzeye oturacaksa temas bölgesini gösterin. Sunum için dijitalleştirilen bir obje söz konusuysa görünmesi gereken yüzeyleri ve kullanım ölçeğini açıklayın."},{"title":"Yüzey verisinden tasarım girdisine","body":"Elde edilen yüzeyin doğrudan görüntülenmesi ile düzenlenebilir bir tasarım referansına dönüştürülmesi ayrı işlemlerdir. Dosyayı hangi yazılımda ve hangi amaçla kullanacağınızı baştan bilmek teslim biçimini belirlemeye yardımcı olur. CAD yeniden çizimi gerekiyorsa bunu tarama talebinde belirtin."},{"title":"Objeyi paylaşmadan önce","body":"Yaklaşık boyut, malzeme görünümü ve hareketli parçaların durumunu not edin. Sökülebilen kapaklar veya gizli yüzeyler varsa fotoğraflarda işaretleyin. Fiziksel gönderimden önce değerlendirme kapsamı ve numunenin geri dönüş şekli görüşülmelidir."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Bir kullanım senaryosuyla başlayın","body":"Ürün kimin elinde, hangi ortamda ve hangi hareketle kullanılacak? Bu sorular gövde biçimi kadar düğme erişimini, açılma yönünü ve taşınabilirliği de etkiler. Referans görsellerinizi beğendiğiniz özelliklerle birlikte paylaşmanız tasarım niyetini anlaşılır kılar."},{"title":"Değişebilir bölgeleri ayırın","body":"Hazır elektronik bileşen, bağlantı elemanı veya korunması gereken dış ölçü sabit girdi olabilir. Buna karşılık form, yüzey geçişi ve kapak düzeni geliştirilebilir alanlardır. İlk görüşmede bu sınırları ayırarak revizyonun nerede yapılabileceğini belirleyelim."},{"title":"Dijital onaydan fiziksel denemeye","body":"Ekrandaki modelde genel formu ve yerleşimi değerlendirdikten sonra kritik bölümleri numuneyle inceleyebilirsiniz. Elde tutuş veya geçme davranışı gibi konular fiziksel geri bildirim gerektirebilir. Sonraki düzenlemeleri aynı dosyanın üzerine belirsiz biçimde eklemek yerine sürümlendirelim."},{"title":"Revizyonu yönetilebilir hale getirin","body":"İlk tasarım görüşmesinde sabit kalacak ölçüleri ve değişebilecek özellikleri listeleyin. Bir kutuda kart ölçüsü sabitken kablo çıkışının yeri değişebilir. Bu ayrım, modelin nasıl kurulacağını etkiler. Kontrol görüntüsü, ölçü listesi ve fiziksel numune onayını farklı aşamalar olarak ele almak, yalnızca görüntü üzerinden verilmiş bir onayın üretim onayıyla karışmasını önler."}]'::jsonb,editorial='{"answer":"3D modelleme; eskiz, teknik resim, ölçü veya tarama referansını üretilebilir dijital tasarıma dönüştürür. Ürün geliştirmede modelin dış görünüşü kadar montaj ilişkileri ve değiştirilebilir ölçüleri de önemlidir. Baskıya uygun ağ dosyası ile sonraki revizyonlarda düzenlenebilen CAD teslimi birlikte planlanabilir.","takeaways":["Dosyayı oluşturmak için mevcut referansları ve eksik ölçüleri ayırın.","Kritik bağlantılar ile yalnızca görsel olan detayları belirtin.","Teslim formatını üretim ve sonraki revizyon ihtiyaçlarına göre seçin."],"comparison":{"title":"Tasarım başlangıç noktaları","columns":["Elinizdeki veri","Çalışma","İlk karar"],"rows":[["Eskiz / fikir","Ölçülü tasarım geliştirme","Dış boyut ve işlev"],["Teknik resim","CAD model oluşturma","Eksik ölçü ve toleranslar"],["Fiziksel örnek","Ölçüm veya tarama destekli modelleme","Kopyalanacak ve değiştirilecek bölgeler"]]},"relatedPaths":["/3d-baski","/3d-tarama","/rehber/3d-baski-mi-cnc-mi"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dyanimda') AND path='/3d-modelleme' AND status='draft' AND sections='[{"title":"Bir kullanım senaryosuyla başlayın","body":"Ürün kimin elinde, hangi ortamda ve hangi hareketle kullanılacak? Bu sorular gövde biçimi kadar düğme erişimini, açılma yönünü ve taşınabilirliği de etkiler. Referans görsellerinizi beğendiğiniz özelliklerle birlikte paylaşmanız tasarım niyetini anlaşılır kılar."},{"title":"Değişebilir bölgeleri ayırın","body":"Hazır elektronik bileşen, bağlantı elemanı veya korunması gereken dış ölçü sabit girdi olabilir. Buna karşılık form, yüzey geçişi ve kapak düzeni geliştirilebilir alanlardır. İlk görüşmede bu sınırları ayırarak revizyonun nerede yapılabileceğini belirleyelim."},{"title":"Dijital onaydan fiziksel denemeye","body":"Ekrandaki modelde genel formu ve yerleşimi değerlendirdikten sonra kritik bölümleri numuneyle inceleyebilirsiniz. Elde tutuş veya geçme davranışı gibi konular fiziksel geri bildirim gerektirebilir. Sonraki düzenlemeleri aynı dosyanın üzerine belirsiz biçimde eklemek yerine sürümlendirelim."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Operasyonun darboğazını tarif edin","body":"Parça hangi adımı kolaylaştıracak: ürünün yönünü sabitlemek, bileşeni yerinde tutmak veya montaj sırasında erişim sağlamak mı? İstasyonun fotoğrafında çalışma alanını işaretleyin. Operatör hareketi ve parçayla temas eden yüzeyler aparat tasarımının sınırlarını belirler."},{"title":"Atölye koşullarına göre numune","body":"Sürtünme, darbe, sürekli yük ve temizlik işlemini ayrı başlıklarda anlatın. Yardımcı parça üzerindeki yükün yönü, geometri ve malzemenin beraber değerlendirilmesini gerektirir. Üretim hattına alınmadan önce deneme yapılacak istasyon ve kontrol sorumlusu belirlenmelidir."},{"title":"Satın alma için izlenebilir parça listesi","body":"Çizim numarası, revizyon, istasyon kodu ve adet bilgisini dosya adıyla eşleştirin. Bir takım halinde çalışacak parçaların listesini ayrıca verin. Onaylanan numunenin hangi koşullarda değerlendirildiğini kaydetmek tekrar siparişin aynı teknik referansa bağlanmasını sağlar."},{"title":"Satın alma ile üretimi aynı dosyada buluşturun","body":"Parça kodu, teknik resim revizyonu ve istenen adedi birlikte paylaşın. Metal insert, burç, mıknatıs veya bağlantı elemanı gereksinimlerini modelden bağımsız bir listeye ekleyin. Teklifin yalnızca baskıyı mı yoksa montaj ve kontrolü de mi kapsadığı açık olduğunda teklifler aynı kapsam üzerinden karşılaştırılabilir."}]'::jsonb,editorial='{"answer":"Endüstriyel 3D baskı; montaj yardımcısı, konumlandırma aparatı ve düşük adetli özel parçaların üretiminde değerlendirilebilir. 3dsanayi için başlangıç noktası operasyondur: parça neyi tutuyor, hangi kuvveti taşıyor ve nasıl kontrol ediliyor? Malzeme ile baskı yönü bu görev üzerinden seçilir.","takeaways":["Sadece CAD dosyasını değil, çalışma istasyonunu da tarif edin.","Aşınan yüzey ile yapısal gövdeyi ayrı değerlendirin.","Numuneyi gerçek çevrim koşulunda deneyerek seri talebini onaylayın."],"comparison":{"title":"Aparat karar matrisi","columns":["Operasyon","Tasarım odağı","Doğrulama"],"rows":[["Montaj konumlandırma","Referans yüzey ve yanlış yerleşimi önleme","Tekrarlanan yerleştirme denemesi"],["Kontrol yardımcısı","Kontrol edilen ölçü ve referans","Ölçüm yöntemiyle kıyas"],["Operatör desteği","Kavrama ve erişim","İstasyon üzerinde kullanım"],["Bakım aparatı","Sökme ve erişim boşluğu","Planlanan bakım adımı"]]},"relatedPaths":["/rehber/fikstur-numune-kabul-plani","/rehber/aparat-malzeme-secimi","/cozumler/montaj-konumlandirma","/3d-modelleme"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/3d-baski' AND status='draft' AND sections='[{"title":"Operasyonun darboğazını tarif edin","body":"Parça hangi adımı kolaylaştıracak: ürünün yönünü sabitlemek, bileşeni yerinde tutmak veya montaj sırasında erişim sağlamak mı? İstasyonun fotoğrafında çalışma alanını işaretleyin. Operatör hareketi ve parçayla temas eden yüzeyler aparat tasarımının sınırlarını belirler."},{"title":"Atölye koşullarına göre numune","body":"Sürtünme, darbe, sürekli yük ve temizlik işlemini ayrı başlıklarda anlatın. Yardımcı parça üzerindeki yükün yönü, geometri ve malzemenin beraber değerlendirilmesini gerektirir. Üretim hattına alınmadan önce deneme yapılacak istasyon ve kontrol sorumlusu belirlenmelidir."},{"title":"Satın alma için izlenebilir parça listesi","body":"Çizim numarası, revizyon, istasyon kodu ve adet bilgisini dosya adıyla eşleştirin. Bir takım halinde çalışacak parçaların listesini ayrıca verin. Onaylanan numunenin hangi koşullarda değerlendirildiğini kaydetmek tekrar siparişin aynı teknik referansa bağlanmasını sağlar."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Ölçüm amacını seçin","body":"Mevcut formu arşivlemek, aşınmış bir parçayı incelemek ve yeniden modellemeye girdi hazırlamak aynı talep değildir. Hangi kararı vereceğinizi yazın. Mil, yuva veya bağlantı ekseni gibi işlevsel referansları işaretlemek ölçüm planını kullanım amacına bağlar."},{"title":"Sahadaki hazırlık bilgileri","body":"Numunenin sökülüp sökülemeyeceğini, taşınabilirliğini ve yaklaşık ağırlığını bildirin. Yağlı, yansıtıcı ya da erişimi kapalı yüzeyleri fotoğrafta gösterin. Yerinde çalışma gereksinimi ve hazırlık adımları ön inceleme yapılmadan kesinleşmiş kabul edilmemelidir."},{"title":"Tarama ile tolerans raporunu ayırın","body":"Bir yüzey ağının oluşması tek başına ölçüsel uygunluk raporu değildir. Karşılaştırılacak nominal model, kritik bölgeler ve istenen rapor kapsamı ayrıca tanımlanmalıdır. Tersine mühendislikte aşınmış yüzey ile korunacak tasarım geometrisinin ayrımı teknik ekiple yapılır."},{"title":"Nominal geometriyi tanımlayın","body":"Uzun süre kullanılmış parçayı yeniden üretirken deformasyonu kopyalamak istemeyebilirsiniz. Hangi yüzeyin tasarım referansı sayılacağına, hangisinin aşındığına ve hangi ölçünün karşı parçadan alınacağına karar verin. Numunenin kullanım geçmişi bilinmiyorsa bu belirsizliği teslim kriterinde açık bırakmak, tarama ile mühendislik yorumunu birbirinden ayırır."}]'::jsonb,editorial='{"answer":"Endüstriyel tarama, mevcut parçanın erişilebilir geometrisini dijital referans haline getirir. Aşınmış bir parçanın ölçülen şekli ile tasarlanmış nominal şekli aynı olmayabilir. 3dsanayi’de talep hazırlanırken montaj referansları, kritik yüzeyler ve tarama sonrasında beklenen CAD veya kontrol çıktısı ayrıştırılır.","takeaways":["Aşınma ve kırıkları referans fotoğraflarında işaretleyin.","Delik eksenleri ve oturma yüzeyleri için kabul ölçülerini tanımlayın.","Tarama sonucu tek başına uygunluk sertifikası değildir."],"comparison":{"title":"Mevcut parçadan hangi bilgi gerekiyor?","columns":["İhtiyaç","Girdi","Teslim kapsamı"],"rows":[["Yedek tasarım","Numune ve montaj bilgisi","Düzenlenebilir CAD kapsamı"],["Geometri arşivi","Erişilebilir yüzeyler","Temizlenmiş tarama ağı"],["Sapma incelemesi","Referans CAD ve hizalama kuralı","Karşılaştırılacak yüzeyler"]]},"relatedPaths":["/3d-modelleme","/rehber/fikstur-numune-kabul-plani","/cozumler/bakim-yardimcilari"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/3d-tarama' AND status='draft' AND sections='[{"title":"Ölçüm amacını seçin","body":"Mevcut formu arşivlemek, aşınmış bir parçayı incelemek ve yeniden modellemeye girdi hazırlamak aynı talep değildir. Hangi kararı vereceğinizi yazın. Mil, yuva veya bağlantı ekseni gibi işlevsel referansları işaretlemek ölçüm planını kullanım amacına bağlar."},{"title":"Sahadaki hazırlık bilgileri","body":"Numunenin sökülüp sökülemeyeceğini, taşınabilirliğini ve yaklaşık ağırlığını bildirin. Yağlı, yansıtıcı ya da erişimi kapalı yüzeyleri fotoğrafta gösterin. Yerinde çalışma gereksinimi ve hazırlık adımları ön inceleme yapılmadan kesinleşmiş kabul edilmemelidir."},{"title":"Tarama ile tolerans raporunu ayırın","body":"Bir yüzey ağının oluşması tek başına ölçüsel uygunluk raporu değildir. Karşılaştırılacak nominal model, kritik bölgeler ve istenen rapor kapsamı ayrıca tanımlanmalıdır. Tersine mühendislikte aşınmış yüzey ile korunacak tasarım geometrisinin ayrımı teknik ekiple yapılır."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Sabit referansları belirleyin","body":"Bağlantı plakası, eksen aralığı ve oturma yüzeyi gibi değişmeyecek ölçüleri ayrı işaretleyin. El ölçüsüyle elde edilen değerlerin belirsizliğini de not edin. Modelin mevcut makine veya takıma nasıl bağlanacağını anlatan montaj görünüşü kapsamı anlaşılır kılar."},{"title":"Bakım ve operatör erişimi","body":"Sökme takma sırası, anahtar erişimi ve temizlenecek boşluklar tasarımın kullanımını etkiler. Geometriyi yalnızca dış sınırlarla tarif etmek bu ihtiyaçları görünmez bırakabilir. Parçanın servis sırasında nasıl ele alınacağını teknik briefin bir bölümü yapın."},{"title":"Revizyon ve teknik teslim","body":"Değişiklik isteğini ilgili parça kodu ve resim üzerinden iletin. Düzenlenebilir CAD, teknik resim ve üretim ağı farklı teslim kalemleridir; hangilerinin beklendiğini sözleşme kapsamına yazın. Onaylanan revizyonun sonraki üretimlere nasıl aktarılacağını baştan kararlaştırın."},{"title":"Onaylı revizyonu üretime bağlayın","body":"Çizimde yapılan değişiklik ile operatörün sahada yaptığı düzeltmenin aynı dosyaya işlenmesi gerekir. Tasarım tesliminde parça numarası ve revizyon kodu kullanın. Numune üzerinde el ile açılmış bir kanal veya eklenmiş bir rondela varsa gerekçesini kaydedin. Tekrar üretim, son onaylı geometri üzerinden yürütülmelidir."}]'::jsonb,editorial='{"answer":"Aparat modelleme, parçanın üretim hattındaki görevini tekrarlanabilir bir geometriye dönüştürür. Referans yüzeyleri, bağlama noktaları, operatör erişimi ve kontrol yöntemleri birlikte düşünülür. 3dsanayi için iyi bir model; yalnızca üretilebilen değil, tanımlanan operasyonda denenebilen ve revizyonu izlenebilen tasarımdır.","takeaways":["Montaj sırasını ve operatörün erişim yönünü tanımlayın.","Standart bağlantı elemanlarını ve değiştirilebilir aşınma bölgelerini belirtin.","Kabul ölçütlerini modelleme başlamadan yazın."],"comparison":{"title":"Aparat briefinin üç katmanı","columns":["Katman","Tanım","Örnek"],"rows":[["Geometri","Parça ve referanslar","Delik ekseni, oturma yüzeyi"],["Operasyon","Kullanıcı ve çevrim","Yerleştirme, sıkma, çıkarma"],["Kabul","Başarı ölçütü","Uyum, erişim ve tekrarlanabilirlik"]]},"relatedPaths":["/rehber/fikstur-numune-kabul-plani","/rehber/aparat-malzeme-secimi","/3d-baski"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='3dsanayi') AND path='/3d-modelleme' AND status='draft' AND sections='[{"title":"Sabit referansları belirleyin","body":"Bağlantı plakası, eksen aralığı ve oturma yüzeyi gibi değişmeyecek ölçüleri ayrı işaretleyin. El ölçüsüyle elde edilen değerlerin belirsizliğini de not edin. Modelin mevcut makine veya takıma nasıl bağlanacağını anlatan montaj görünüşü kapsamı anlaşılır kılar."},{"title":"Bakım ve operatör erişimi","body":"Sökme takma sırası, anahtar erişimi ve temizlenecek boşluklar tasarımın kullanımını etkiler. Geometriyi yalnızca dış sınırlarla tarif etmek bu ihtiyaçları görünmez bırakabilir. Parçanın servis sırasında nasıl ele alınacağını teknik briefin bir bölümü yapın."},{"title":"Revizyon ve teknik teslim","body":"Değişiklik isteğini ilgili parça kodu ve resim üzerinden iletin. Düzenlenebilir CAD, teknik resim ve üretim ağı farklı teslim kalemleridir; hangilerinin beklendiğini sözleşme kapsamına yazın. Onaylanan revizyonun sonraki üretimlere nasıl aktarılacağını baştan kararlaştırın."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Sunumda ne görünmeli?","body":"Bir satış maketinde cephe etkisi öne çıkarken bir tasarım toplantısında kütle ilişkisi belirleyici olabilir. Maketin hangi karar veya anlatım için kullanılacağını paylaşın. Gereksiz ayrıntıları azaltıp görünür olması gereken bölgelerin okunabilirliğine odaklanabiliriz."},{"title":"Ölçeğe bağlı parça ayrımı","body":"Kaynak modelin birimiyle hedef maket ölçeğini birlikte belirtin. Çok ince elemanların temsil yöntemi ve farklı malzemelerle tamamlanacak bölümler önceden belirlenmelidir. Üretim sınırı kadar paketleme ölçüsü de maketin nereden bölüneceğini etkiler."},{"title":"Taban ve birleştirme düzeni","body":"Kütlelerin sökülebilir olup olmayacağını, tabana nasıl yerleşeceğini ve görünen birleşim çizgilerini konuşalım. Boyama veya aydınlatma planı varsa bağlantı ve kablo alanları tasarıma işlenmelidir. Teslim parçalarını yerleşim şemasıyla eşleştirmek montajı kolaylaştırır."},{"title":"Baskı bölümlerini sunum çizgilerine yerleştirin","body":"Maket tek parça üretilemiyorsa birleşim yerlerini rastgele belirlemeyin. Kat döşemeleri, cephe kırıkları veya arazi sınırları doğal ayırma çizgileri sunabilir. Taşıma sonrası kurulacak makette her modülün yerini ve yönünü tarif eden basit bir montaj planı hazırlamak, sunum anındaki kurulumu kolaylaştırır."}]'::jsonb,editorial='{"answer":"Mimari maket baskısı, proje geometrisini seçilen ölçekte fiziksel sunuma dönüştürür. maketyanımda’da ölçek; bina yüksekliği, cephe detaylarının okunması ve maketin taşınmasıyla birlikte değerlendirilir. Tek parça baskı veya modüler kurgu kararı, gösterilecek hikâyeye ve teslim ölçülerine göre verilir.","takeaways":["Sunum mesafesi ve hedef kitle, detay seviyesini belirler.","Ölçek küçüldükçe bazı elemanların sadeleştirilmesi gerekir.","Taban, taşıma kutusu ve birleştirme planını baştan düşünün."],"comparison":{"title":"Maket sunumuna göre baskı yaklaşımı","columns":["Sunum","Öncelik","Hazırlık"],"rows":[["Kütle çalışması","Oran ve komşuluk","Sadeleştirilmiş hacimler"],["Proje tanıtımı","Cephe ve çevre ilişkisi","Görünür detay listesi"],["Kesit anlatımı","İç mekân ve kat ilişkisi","Ayrılabilir kat planı"],["Yerleşim","Topoğrafya ve erişim","Taban ölçüsü ve sınırlar"]]},"relatedPaths":["/rehber/mimari-maket-olcek-secimi","/rehber/maket-fiyati-teklif-kapsami","/cozumler/mimari-kutle-calismalari","/3d-modelleme"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/3d-baski' AND status='draft' AND sections='[{"title":"Sunumda ne görünmeli?","body":"Bir satış maketinde cephe etkisi öne çıkarken bir tasarım toplantısında kütle ilişkisi belirleyici olabilir. Maketin hangi karar veya anlatım için kullanılacağını paylaşın. Gereksiz ayrıntıları azaltıp görünür olması gereken bölgelerin okunabilirliğine odaklanabiliriz."},{"title":"Ölçeğe bağlı parça ayrımı","body":"Kaynak modelin birimiyle hedef maket ölçeğini birlikte belirtin. Çok ince elemanların temsil yöntemi ve farklı malzemelerle tamamlanacak bölümler önceden belirlenmelidir. Üretim sınırı kadar paketleme ölçüsü de maketin nereden bölüneceğini etkiler."},{"title":"Taban ve birleştirme düzeni","body":"Kütlelerin sökülebilir olup olmayacağını, tabana nasıl yerleşeceğini ve görünen birleşim çizgilerini konuşalım. Boyama veya aydınlatma planı varsa bağlantı ve kablo alanları tasarıma işlenmelidir. Teslim parçalarını yerleşim şemasıyla eşleştirmek montajı kolaylaştırır."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Taranacak öğeyi sınırlayın","body":"Cephe detayı, küçük heykel veya elde yapılmış tasarım maketi için farklı çalışma ölçekleri söz konusudur. Numunenin boyutunu ve erişilebilir yüzeylerini fotoğraflarla paylaşın. Bu hizmeti bir yapının tamamına ilişkin ölçüm ya da röleve kapsamıyla karıştırmadan hedef öğeyi belirleyelim."},{"title":"Küçültme sırasında detay kararı","body":"Fiziksel referanstaki her iz hedef maket ölçeğinde okunmayabilir. Yüzey dokusunun korunacağı alanlarla sadeleştirilecek çizgileri ayırın. Tarama sonrasında sunum modeline uyarlama isteniyorsa bu düzenleme çalışması ayrıca kapsamlandırılır."},{"title":"Özgün eserin korunması","body":"Kırılgan veya değerli bir obje söz konusuysa taşıma ve temas kısıtlarını önceden bildirin. Numunenin gönderimi, kabul koşulları ve çalışma yöntemi teyit edilmeden planlanmamalıdır. Dijitalleştirme yetkisi ve çoğaltma hakkı proje sahibince değerlendirilmelidir."},{"title":"Ölçek değişince detayları yeniden değerlendirin","body":"Büyük bir objenin taramasını küçük makete dönüştürürken bütün ayrıntılar aynı biçimde üretilemez. İnce çıkıntılar, derin oyuklar ve boşlukların son boyuttaki karşılığını inceleyin. Temizlenmiş tarama görüntüsünün ekranda iyi görünmesi, küçültülmüş fiziksel maketin aynı okunabilirlikte olacağını tek başına göstermez."}]'::jsonb,editorial='{"answer":"Maket için 3D tarama; mevcut obje, heykel veya fiziksel tasarımın dijital referansını elde etmeye yardımcı olur. Çıktının yeniden ölçeklenmesi, temizlenmesi ve baskıya hazırlanması ayrıca değerlendirilir. maketyanımda için temel soru, hangi karakteristik detayın son makette okunması gerektiğidir.","takeaways":["Son maket boyutunu tarama kapsamıyla birlikte paylaşın.","Yüzey dokusu ile geometrik detayın aynı bilgi olmadığını dikkate alın.","Kaide ve objenin birbirine nasıl bağlanacağını tanımlayın."],"comparison":{"title":"Fiziksel referanstan makete","columns":["Referans","Karar","İstenen çıktı"],"rows":[["Heykel / obje","Korunacak karakteristikler","Temizlenmiş yüzey ağı"],["Elde hazırlanmış model","Son sunum ölçeği","Baskıya uygun model"],["Mevcut detay","Yeni tasarımla birleşim","Referans geometri ve uyarlama"]]},"relatedPaths":["/rehber/mimari-maket-olcek-secimi","/3d-baski","/3d-modelleme"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/3d-tarama' AND status='draft' AND sections='[{"title":"Taranacak öğeyi sınırlayın","body":"Cephe detayı, küçük heykel veya elde yapılmış tasarım maketi için farklı çalışma ölçekleri söz konusudur. Numunenin boyutunu ve erişilebilir yüzeylerini fotoğraflarla paylaşın. Bu hizmeti bir yapının tamamına ilişkin ölçüm ya da röleve kapsamıyla karıştırmadan hedef öğeyi belirleyelim."},{"title":"Küçültme sırasında detay kararı","body":"Fiziksel referanstaki her iz hedef maket ölçeğinde okunmayabilir. Yüzey dokusunun korunacağı alanlarla sadeleştirilecek çizgileri ayırın. Tarama sonrasında sunum modeline uyarlama isteniyorsa bu düzenleme çalışması ayrıca kapsamlandırılır."},{"title":"Özgün eserin korunması","body":"Kırılgan veya değerli bir obje söz konusuysa taşıma ve temas kısıtlarını önceden bildirin. Numunenin gönderimi, kabul koşulları ve çalışma yöntemi teyit edilmeden planlanmamalıdır. Dijitalleştirme yetkisi ve çoğaltma hakkı proje sahibince değerlendirilmelidir."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Mimari dosyanın temizlenmesi","body":"Sunum için görünmeyecek iç elemanlar, çakışan yüzeyler ve tekrar eden bileşenler modelin hazırlığını zorlaştırabilir. Kaynak dosya ile hedef maket kapsamını karşılaştırarak gerekli öğeleri seçelim. Mimari tasarım kararları ile üretim için yapılacak sadeleştirmeleri ayrı onaylayın."},{"title":"Cephe ritmini koruyan sadeleştirme","body":"Pencere, saçak ve korkuluk gibi öğeler küçük ölçekte yeniden yorumlanabilir. Hangi görünüşün öncelikli olduğunu belirtin; karakteri taşıyan çizgileri koruyarak okunabilirliği değerlendirelim. Dijital ön izlemede farklı detay seviyelerini karşılaştırmak karar vermeyi kolaylaştırır."},{"title":"Kurulum için kodlanmış model","body":"Ayrı üretilecek kütleleri, taban bölümlerini ve peyzaj öğelerini düzenli adlandırın. Birleştirme yönleri ile görünmeyecek bağlantı yüzeyleri modelde tanımlanmalıdır. Maket başka bir ekip tarafından kurulacaksa yerleşim şeması ve parça numarası teslim ihtiyacını belirtin."},{"title":"Sunum kapsamını bir görünüş listesiyle sabitleyin","body":"Projenin hangi açılardan izleneceğini ve hangi katların açılacağını işaretleyin. Bu liste sayesinde görünmeyen detaylara ayrılacak süre, anlatımı güçlendirecek alanlara aktarılabilir. Proje revize olduğunda yalnızca dosya adını değil, değişen kütleleri ve cepheleri de bildirin; baskıya hazırlanmış modüllerin hangilerinin yenileneceği bu bilgiyle belirlenir."}]'::jsonb,editorial='{"answer":"Maket modelleme, mimari dosyayı doğrudan küçültmekten daha fazlasıdır. Sunum ölçeğinde görünmeyecek detaylar sadeleştirilir; ince duvarlar, ayrılabilir katlar ve modül birleşimleri yeniden düzenlenir. maketyanımda’da dijital proje ile fiziksel anlatım arasındaki bu dönüşüm teslim kapsamının bir parçasıdır.","takeaways":["Kullanılacak mimari revizyonu tek kaynak dosya olarak belirleyin.","Maketin göstereceği ve gizleyeceği alanları listeleyin.","Taban, etiket ve sökülebilir parçaları modele dâhil edin."],"comparison":{"title":"Mimari dosyadan fiziksel anlatıma","columns":["Konu","Modelleme kararı","Kontrol"],"rows":[["Cephe","Görünür detayların seçimi","Ölçekte okunabilirlik"],["İç mekân","Katların ayrılması","Erişim ve kesit yönü"],["Arazi","Kotların ve sınırların düzenlenmesi","Tabanla birleşim"]]},"relatedPaths":["/rehber/maket-fiyati-teklif-kapsami","/rehber/mimari-maket-olcek-secimi","/3d-baski"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='maketyanimda') AND path='/3d-modelleme' AND status='draft' AND sections='[{"title":"Mimari dosyanın temizlenmesi","body":"Sunum için görünmeyecek iç elemanlar, çakışan yüzeyler ve tekrar eden bileşenler modelin hazırlığını zorlaştırabilir. Kaynak dosya ile hedef maket kapsamını karşılaştırarak gerekli öğeleri seçelim. Mimari tasarım kararları ile üretim için yapılacak sadeleştirmeleri ayrı onaylayın."},{"title":"Cephe ritmini koruyan sadeleştirme","body":"Pencere, saçak ve korkuluk gibi öğeler küçük ölçekte yeniden yorumlanabilir. Hangi görünüşün öncelikli olduğunu belirtin; karakteri taşıyan çizgileri koruyarak okunabilirliği değerlendirelim. Dijital ön izlemede farklı detay seviyelerini karşılaştırmak karar vermeyi kolaylaştırır."},{"title":"Kurulum için kodlanmış model","body":"Ayrı üretilecek kütleleri, taban bölümlerini ve peyzaj öğelerini düzenli adlandırın. Birleştirme yönleri ile görünmeyecek bağlantı yüzeyleri modelde tanımlanmalıdır. Maket başka bir ekip tarafından kurulacaksa yerleşim şeması ve parça numarası teslim ihtiyacını belirtin."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Parça neden değişecek?","body":"Kaybolan bir kapağın yerine yenisini yapmakla sürekli kırılan bir bağlantıyı yeniden tasarlamak farklı ihtiyaçlardır. Arızanın nasıl oluştuğunu ve parçanın hangi yüzeylerden tutulduğunu anlatın. Sağlam eş parça veya montaj fotoğrafı varsa ölçü ve form değerlendirmesine ekleyin."},{"title":"Bağlantı noktasını görünür kılın","body":"Tırnak, vida, mil veya geçme yüzeyi parçanın yerine oturmasını belirler. Fotoğrafları yalnızca önden çekmek yerine bu bölgeleri de gösterin. Esnemesi beklenen alanlar ve sökme takma sırası, üretim yönü ile malzeme seçiminin birlikte düşünülmesini gerektirir."},{"title":"Kullanım sınırını açıkça belirtin","body":"Güneş gören araç içi, nemli ortam veya hareketli mekanizma aynı koşulları taşımaz. Yeni parçanın nerede çalışacağını yazın. Güvenliği etkileyen işlevlerde fiziksel benzerlik yeterli kabul edilmez; uygunluk ve doğrulama ayrıca ele alınmalıdır."},{"title":"Uyum denemesini siparişin parçası yapın","body":"İlk örneği takarken zorlanan bölgeyi fotoğrafta işaretleyin. Vida deliğini büyütmek, tırnağı kısaltmak veya kenarı zımparalamak gerekiyorsa bu düzeltmeyi modele geri taşıyın. Aynı görünen araç veya cihazlarda farklı revizyonlar bulunabileceği için uyumu yalnızca model adı üzerinden varsaymayın."}]'::jsonb,editorial='{"answer":"Özel parça baskısı, standart olarak bulunmayan plastik kapak, adaptör ve bağlantı parçalarının proje bazında üretilmesinde değerlendirilebilir. parçayanımda için eşleşen yüzey, çalışma sıcaklığı ve montaj şekli birlikte incelenir. Numune uyumu doğrulanmadan aynı tasarımın çoklu üretimine geçilmez.","takeaways":["Parçanın tek başına fotoğrafı yerine montaj yerini de gösterin.","Esneyen tırnak ile sabit gövdenin görevleri farklıdır.","Araç ve makinede güvenlik açısından kritik uygulamalar ayrıca mühendislik doğrulaması gerektirir."],"comparison":{"title":"Parça işlevine göre ilk değerlendirme","columns":["Parça","Önemli bilgi","İlk kontrol"],"rows":[["Kapak / trim","Bağlantı noktaları ve görünür yüzey","Oturma ve sökme denemesi"],["Adaptör","İki tarafın eşleşme ölçüsü","Geçme ve hizalama"],["Tutucu","Yük ve montaj yönü","Bağlantı ve kullanım denemesi"],["Esnek detay","Hareket ve tekrar sayısı","Esneme davranışı"]]},"relatedPaths":["/rehber/kirik-parca-yeniden-uretim","/rehber/otomotiv-plastik-parca-malzeme","/cozumler/ozel-adaptorler","/3d-modelleme"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/3d-baski' AND status='draft' AND sections='[{"title":"Parça neden değişecek?","body":"Kaybolan bir kapağın yerine yenisini yapmakla sürekli kırılan bir bağlantıyı yeniden tasarlamak farklı ihtiyaçlardır. Arızanın nasıl oluştuğunu ve parçanın hangi yüzeylerden tutulduğunu anlatın. Sağlam eş parça veya montaj fotoğrafı varsa ölçü ve form değerlendirmesine ekleyin."},{"title":"Bağlantı noktasını görünür kılın","body":"Tırnak, vida, mil veya geçme yüzeyi parçanın yerine oturmasını belirler. Fotoğrafları yalnızca önden çekmek yerine bu bölgeleri de gösterin. Esnemesi beklenen alanlar ve sökme takma sırası, üretim yönü ile malzeme seçiminin birlikte düşünülmesini gerektirir."},{"title":"Kullanım sınırını açıkça belirtin","body":"Güneş gören araç içi, nemli ortam veya hareketli mekanizma aynı koşulları taşımaz. Yeni parçanın nerede çalışacağını yazın. Güvenliği etkileyen işlevlerde fiziksel benzerlik yeterli kabul edilmez; uygunluk ve doğrulama ayrıca ele alınmalıdır."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Hasarı kopyalamadan referans toplamak","body":"Kırık kenar veya aşınmış yuva, parçanın özgün tasarımını göstermeyebilir. Tarama talebinde bu bölgeleri fotoğraflarla işaretleyin. Simetrik eş, sağlam karşı parça ya da eski ölçü bilgisi varsa eksik geometrinin yorumlanmasına yardımcı olur."},{"title":"Görünmeyen bağlantı yüzeyleri","body":"Dış kabuk kolay görülse bile iç tırnaklar ve dar kanallar tarama kapsamını zorlaştırabilir. Parçanın sökülebilen bölümlerini ve erişilemeyen bağlantılarını bildirin. Hangi yüzeylerin başka yöntemlerle ölçülmesi gerekeceği teknik değerlendirmede belirlenir."},{"title":"Yeniden üretime geçiş","body":"Sayısallaştırılan yüzey, baskıya veya düzenlenebilir CAD dosyasına dönüşmeden önce onarım ve modelleme gerektirebilir. Talebiniz yalnızca dijital kayıt mı, yoksa yerine oturan yeni parça mı? Beklenen çıktıyı baştan tanımlamak işin kapsamını netleştirir."},{"title":"Montaj yerini de belgeleyin","body":"Kapağın tek yüzünü taramak bağlantı tırnağının nasıl çalıştığını açıklamayabilir. Montaj yuvasının fotoğrafları, vida konumları ve parça takılıyken kalan boşluk üretim kararına yardımcı olur. Numunenin kalıcı biçimde eğildiği veya aşındığı bölgeleri belirtmek, hatalı şeklin aynen çoğaltılmasını önler."}]'::jsonb,editorial='{"answer":"Örnek parçanın taranması, mevcut dış yüzeyin dijital referansını oluşturur. Kırık veya eksik bölgeler taramayla kendiliğinden geri gelmez; karşı parça, sağlam örnek veya ölçülerle yeniden tasarlanır. parçayanımda’da hedef, görünen şeklin yanında montajda işe yarayan geometriyi de tanımlamaktır.","takeaways":["Kırık parçanın bütün parçacıklarını mümkünse saklayın.","Sağ ve sol parçanın simetrik olduğunu ölçmeden varsaymayın.","Tarama sonrasında gereken onarım ve CAD çalışmasını ayrı belirtin."],"comparison":{"title":"Numunenin durumuna göre yaklaşım","columns":["Numune","Ek bilgi","Modelleme ihtiyacı"],"rows":[["Sağlam örnek","Kritik montaj ölçüleri","Üretime uyarlama"],["Kırık örnek","Eksik alanın fotoğrafı ve karşı parça","Geometri tamamlama"],["Deforme örnek","Beklenen nominal ölçüler","Şeklin mühendislik yorumu"]]},"relatedPaths":["/rehber/kirik-parca-yeniden-uretim","/3d-modelleme","/cozumler/ornekten-parca-modelleme"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/3d-tarama' AND status='draft' AND sections='[{"title":"Hasarı kopyalamadan referans toplamak","body":"Kırık kenar veya aşınmış yuva, parçanın özgün tasarımını göstermeyebilir. Tarama talebinde bu bölgeleri fotoğraflarla işaretleyin. Simetrik eş, sağlam karşı parça ya da eski ölçü bilgisi varsa eksik geometrinin yorumlanmasına yardımcı olur."},{"title":"Görünmeyen bağlantı yüzeyleri","body":"Dış kabuk kolay görülse bile iç tırnaklar ve dar kanallar tarama kapsamını zorlaştırabilir. Parçanın sökülebilen bölümlerini ve erişilemeyen bağlantılarını bildirin. Hangi yüzeylerin başka yöntemlerle ölçülmesi gerekeceği teknik değerlendirmede belirlenir."},{"title":"Yeniden üretime geçiş","body":"Sayısallaştırılan yüzey, baskıya veya düzenlenebilir CAD dosyasına dönüşmeden önce onarım ve modelleme gerektirebilir. Talebiniz yalnızca dijital kayıt mı, yoksa yerine oturan yeni parça mı? Beklenen çıktıyı baştan tanımlamak işin kapsamını netleştirir."}]'::jsonb;

UPDATE public.landing_pages SET sections='[{"title":"Karşı parçadan başlayan tasarım","body":"Adaptörün iki ucunda bağlanacağı yüzeyleri, kontrol düğmesinin oturacağı mili veya kapağın kapanacağı çerçeveyi tarif edin. Yalnızca dış görünüş bağlantı geometrisini açıklamaz. Değişmeyecek ölçüler ile uyarlanabilecek gövde bölgelerini ayrı işaretleyin."},{"title":"Sökülebilirlik ve esneme","body":"Bir klipsin takılma yönü, esneyen kolu ve duracağı yüzey aynı tasarımın parçalarıdır. Kaç kez açılıp kapanacağı ve hangi aletle söküleceği gibi kullanım beklentilerini paylaşın. İlk fiziksel denemenin sonucu üzerinden geometriyi revize etmek gerekebilir."},{"title":"Kişiye veya ürüne özel uyarlama","body":"Hazır bir bağlantıyı farklı ölçüye uyarlarken yalnızca modeli büyütmek yeterli olmayabilir. Vida, mil veya cihaz ölçüleri sabit kalırken gövde değişebilir. Talepte korunacak bağlantı standartlarını ve yeni yerleşim alanını birbirinden ayırın."},{"title":"Kopyalama ile iyileştirmeyi ayırın","body":"Mevcut parçayı aynen üretmek ile duvar kalınlığını, bağlantıyı veya montaj yönünü değiştirmek farklı işlerdir. Talebinizde hangi ölçülerin korunacağını yazın. İyileştirme istenen alanların gerçek montajda denenmesi gerekir; daha kalın bir gövde her zaman daha iyi uyum veya doğru esneme anlamına gelmez."}]'::jsonb,editorial='{"answer":"Özel parça modelleme, örneğin görünüşünü montaj ölçüleriyle birleştirerek üretilebilir geometri oluşturur. parçayanımda’da kapak, tutucu ve adaptörler için önce eşleşen arayüzler tanımlanır. Sonrasında gövde, bağlantı ve esneme detayları seçilen üretim yaklaşımına göre düzenlenir.","takeaways":["Kritik ölçüleri ve ölçünün alındığı yüzeyi işaretleyin.","İstenen değişikliği orijinal parçadan ayrı bir listede anlatın.","Son dosyanın revizyonunu uyumu denenmiş numuneyle eşleştirin."],"comparison":{"title":"Modellemeyi başlatacak referanslar","columns":["Referans","Yeterli olduğu alan","Eksik kalabilecek bilgi"],"rows":[["Ölçülü çizim","Tanımlı yüzey ve mesafeler","Gizli geometri"],["Fiziksel parça","Şekil ve montaj ilişkisi","Eksik / aşınmış bölgeler"],["Fotoğraf","İşlev ve görünüş","Kesin ölçü ve derinlik"]]},"relatedPaths":["/rehber/kirik-parca-yeniden-uretim","/rehber/otomotiv-plastik-parca-malzeme","/3d-baski"]}'::jsonb,updated_at='2026-10-06T15:00:00Z' WHERE tenant_id IN (SELECT id FROM public.tenants WHERE slug='parcayanimda') AND path='/3d-modelleme' AND status='draft' AND sections='[{"title":"Karşı parçadan başlayan tasarım","body":"Adaptörün iki ucunda bağlanacağı yüzeyleri, kontrol düğmesinin oturacağı mili veya kapağın kapanacağı çerçeveyi tarif edin. Yalnızca dış görünüş bağlantı geometrisini açıklamaz. Değişmeyecek ölçüler ile uyarlanabilecek gövde bölgelerini ayrı işaretleyin."},{"title":"Sökülebilirlik ve esneme","body":"Bir klipsin takılma yönü, esneyen kolu ve duracağı yüzey aynı tasarımın parçalarıdır. Kaç kez açılıp kapanacağı ve hangi aletle söküleceği gibi kullanım beklentilerini paylaşın. İlk fiziksel denemenin sonucu üzerinden geometriyi revize etmek gerekebilir."},{"title":"Kişiye veya ürüne özel uyarlama","body":"Hazır bir bağlantıyı farklı ölçüye uyarlarken yalnızca modeli büyütmek yeterli olmayabilir. Vida, mil veya cihaz ölçüleri sabit kalırken gövde değişebilir. Talepte korunacak bağlantı standartlarını ve yeni yerleşim alanını birbirinden ayırın."}]'::jsonb;

INSERT INTO public.landing_pages(tenant_id,path,title,summary,kind,image,status,sections,faq,editorial) SELECT id,'/rehber/prototip-maliyetini-ne-belirler','Prototip maliyetini ne belirler?','3D baskı teklifini gramajdan öte okuyun: dosya hazırlığı, geometri, numune, revizyon ve tekrar üretim maliyetini aynı kapsamda değerlendirin.','guide','','draft','[{"title":"İlk sipariş ile tekrar siparişi ayırın","body":"İlk üretimde dosya düzeltme, ölçü tamamlama veya baskı yönünü belirleme çalışması gerekebilir. Bu hazırlıklar, onaylı aynı dosyanın tekrarında aynı kapsamda tekrarlanmayabilir. Teklifte tek seferlik hazırlık kalemini, parça başı üretimi ve her siparişte gerekli kontrolü ayrı görmek toplam bütçeyi anlamayı kolaylaştırır. Tasarım değişirse eski tekrar fiyatının otomatik olarak geçerli olduğunu varsaymayın."},{"title":"Geometri neden fiyatı değiştirir?","body":"İnce ve yüksek bir parça, aynı hacimde daha alçak bir parçadan farklı baskı süresine sahip olabilir. Destek ihtiyacı olan yüzeyler temizleme işi doğurur. Birbiri içine kapanan boşluklar ise üretim yönü veya geometri değişikliği gerektirebilir. Dosyayı teklif öncesinde inceletmek, görünüşte küçük bir ayrıntının süreye ve son işleme etkisini görmenizi sağlar."},{"title":"Hangi detay gerçekten gerekli?","body":"Numunenin bir toplantıda görünüş anlatmak için mi, montaj kontrolü için mi kullanılacağını belirtin. Görünmeyecek bir alt yüzeyde kozmetik kalite aramak ya da yalnızca sunumda kullanılacak parça için çalışma ortamına yönelik gereksiz talepler eklemek kapsamı büyütebilir. Buna karşılık çalışan prototipte kritik ölçü veya malzemeyi yalnızca maliyet düşürmek için değiştirmek denemenin amacını bozabilir."},{"title":"Karşılaştırılabilir teklif dosyası hazırlayın","body":"Tek bir revizyon klasörü oluşturun: model, varsa teknik resim, adet, kullanım açıklaması ve onay ölçütü. Teklife modelleme, montaj, bağlantı elemanları, son işlem ve teslimatın dâhil olup olmadığını sorun. “Bir adet ilk numune, onaydan sonra ayrı miktar” biçimindeki talep, bütün sayıyı test edilmemiş tasarımla sipariş etme riskini azaltır."}]'::jsonb,'[{"q":"Dosyam olmadan fiyat alabilir miyim?","a":"Fotoğraf, yaklaşık ölçü ve kullanım amacıyla ön kapsam görüşü alınabilir. Kesin üretim teklifi için geometrinin ve modelleme ihtiyacının netleşmesi gerekir."},{"q":"Çok adet her zaman daha ucuz mu?","a":"Parça başı hazırlık paylaşılabilir, ancak toplam üretim süresi, son işlem ve kontrol ihtiyacı devam eder. Adet etkisi dosya ve üretim düzenine göre değerlendirilir."},{"q":"Teklif tutarı neden dosya değişince güncellenir?","a":"Ölçü, duvar, destek ihtiyacı ve baskı yönü değişiklikleri üretim süresini veya malzeme kullanımını değiştirebilir. Yeni revizyon yeni kapsam olarak kontrol edilmelidir."}]'::jsonb,'{"answer":"Prototip maliyeti; modelleme ve dosya hazırlığı, baskı süresi, malzeme, destek temizliği, son işlem ve doğrulama kapsamından oluşur. Aynı ağırlıktaki iki parça farklı süre ve işçilik gerektirebilir. Sağlıklı fiyat karşılaştırması için bütün tekliflerde aynı dosya revizyonu, adet ve teslim beklentisi kullanılmalıdır.","takeaways":["“Gram fiyatı” toplam proje maliyetini tek başına açıklamaz.","İlk numune ile onaylı dosyanın tekrar baskısını ayrı fiyatlandırın.","Kritik yüzeyler dışında gereksiz son işlemi azaltabilirsiniz."],"comparison":{"title":"Teklifte hangi kalem nerede oluşur?","columns":["Kalem","İlk numune","Tekrar üretim"],"rows":[["Model hazırlığı","Mevcut dosyaya bağlı","Revizyon yoksa kapsam yeniden kontrol edilir"],["Baskı","Geometri ve ayarlara bağlı","Adet ve yerleşime bağlı"],["Son işlem","İstenen yüzeye bağlı","Her parça için değerlendirilir"],["Kontrol","Kabul planı belirlenir","Belirlenen plana göre yürütülür"]]},"relatedPaths":["/3d-baski","/3d-modelleme","/rehber/3d-baski-mi-cnc-mi"]}'::jsonb FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT (tenant_id,path) DO NOTHING;

INSERT INTO public.landing_pages(tenant_id,path,title,summary,kind,image,status,sections,faq,editorial) SELECT id,'/rehber/3d-baski-mi-cnc-mi','Prototip için 3D baskı mı, CNC mi?','Yöntem seçimini parça geometrisi, malzeme, adet ve test amacı üzerinden yapın; ilk prototip ile nihai üretim için aynı yöntemi seçmek zorunda değilsiniz.','guide','','draft','[{"title":"Önce test sorusunu yazın","body":"“Elime nasıl oturuyor?” ile “bu yük altında nasıl davranıyor?” farklı prototip sorularıdır. Ergonomi incelemesinde dış geometri yeterli olabilir; işlevsel denemede malzeme ve üretim yönü belirleyici hale gelir. İlk toplantıda prototipin cevaplaması gereken üç soruyu yazmak, gereğinden pahalı veya amaca uygun olmayan yöntemi seçmeyi önler."},{"title":"Geometriyi üretim erişimiyle karşılaştırın","body":"CNC işleme için takımın yüzeye erişmesi gerekir. Baskıda ise desteklerin yerleşimi ve sonradan temizlenmesi düşünülür. Bir yöntemde kolay olan kapalı veya derin bir ayrıntı diğerinde farklı kurgu isteyebilir. Parçayı bölmek, montaj eklemek ya da tasarımı sadeleştirmek gibi seçeneklerin kullanım üzerindeki etkisini dosya üzerinden değerlendirin."},{"title":"Malzeme adı tek başına eşdeğerlik değildir","body":"Aynı ailedeki malzemeler üretim biçimi ve ürün sınıfına göre farklı davranabilir. Katmanlı imalatla üretilen bir numunenin bütün yönlerde aynı performansı verdiğini varsaymayın. Yük yönünü, sıcaklığı, ortamı ve kabul kriterini paylaşın. Testin sonucu yalnızca denenmiş malzeme, geometri ve koşullar için anlamlıdır."},{"title":"İki aşamalı prototip planı kurun","body":"İlk aşamada geometri ve montajı, ikinci aşamada gerekli işlevi doğrulamak bazı projelerde daha kontrollü ilerleme sağlar. Ancak ek numune ve teslim sürelerini bütçeye dâhil edin. Farklı yöntemlerle hazırlanmış teklifleri kıyaslarken dosya revizyonu, yüzey işlemi ve kontrol kapsamının aynı olduğundan emin olun."}]'::jsonb,'[{"q":"Hangi yöntem daha ucuz?","a":"Geometri, malzeme, adet ve hazırlık ihtiyacı bilinmeden genel bir fiyat sıralaması yapılamaz. Aynı kullanım hedefi için kapsamı eşitlenmiş teklifler karşılaştırılmalıdır."},{"q":"3D baskı numunesi seri ürünü temsil eder mi?","a":"Görünüş veya montaj açısından temsil edebilir. Farklı malzeme ve üretim yöntemindeki seri ürünün mekanik davranışını tek başına doğrulamaz."},{"q":"İki yöntemi bir projede kullanabilir miyim?","a":"Üretim planı uygunsa farklı parçalar veya revizyonlar için ayrı yöntemler değerlendirilebilir. Montaj arayüzleri ve teslim sorumlulukları birlikte tanımlanmalıdır."}]'::jsonb,'{"answer":"3D baskı ile CNC arasında seçim yaparken parçanın neyi kanıtlayacağını belirleyin. Görünüş ve ilk montaj denemesinde hızlı tasarım değişikliği ön plandayken, belirli malzeme ve hassas işlenmiş yüzey ihtiyacı farklı yöntem gerektirebilir. Karar yalnızca birim fiyatla değil, hazırlık, test ve revizyon toplamıyla verilmelidir.","takeaways":["Bir prototipin malzemesi, nihai ürünün malzemesiyle aynı olmayabilir.","Karmaşık iç geometri ve işleme erişimini birlikte inceleyin.","Üretim yöntemini değiştirirken eski test sonucunu doğrudan genellemeyin."],"comparison":{"title":"Seçim görüşmesine götürülecek sorular","columns":["Başlık","3D baskı değerlendirmesi","CNC değerlendirmesi"],"rows":[["Geometri","Destek ve katman yönü","Takım erişimi ve bağlama"],["Revizyon","Yeni baskı düzeni","Program ve bağlama değişikliği"],["Malzeme","Yazdırılabilir malzeme ve yön etkisi","İşlenebilir stok malzeme"],["Son kontrol","Kritik ölçü ve yüzey denemesi","Kritik ölçü ve yüzey denemesi"]]},"relatedPaths":["/3d-baski","/rehber/prototip-maliyetini-ne-belirler","/cozumler/urun-gelistirme-prototipleri"]}'::jsonb FROM public.tenants WHERE slug='3dyanimda' ON CONFLICT (tenant_id,path) DO NOTHING;

INSERT INTO public.landing_pages(tenant_id,path,title,summary,kind,image,status,sections,faq,editorial) SELECT id,'/rehber/fikstur-numune-kabul-plani','3D baskı fikstür için numune kabul planı','Montaj aparatını üretim hattına almadan önce uyum, referanslama, operatör erişimi ve tekrar kullanım için kontrol maddeleri oluşturun.','guide','','draft','[{"title":"Parçanın oturduğu referansları tanımlayın","body":"Fikstürün hangi yüzeyler üzerinden konumlandırdığını teknik resimde işaretleyin. Hareket etmesi gereken eksenleri ve sabit tutulacak eksenleri ayrı belirtin. Parça yerleştiğinde oluşan boşluğu veya sıkışmayı gözlemlemek için kontrol yöntemi seçin. Referans alınan iş parçasının ölçü durumu bilinmiyorsa numune sonucunun bu belirsizliği de içerdiğini kaydedin."},{"title":"Operatörün yaptığı hareketi deneyin","body":"Aparata erişim, parçayı yerleştirme yönü, bağlama elemanlarına ulaşma ve iş parçasını çıkarma adımlarını gerçek istasyonda inceleyin. Eldiven kullanımı veya farklı operatör boyları gibi koşulları değerlendirmeye alın. Bir fotoğraf üzerinde rahat görünen boşluk, gerçek el hareketi ve kullanılan aletlerle yeterli olmayabilir. Gözlemleri operasyon sırasına göre yazın."},{"title":"Deneme koşullarını kayıt altına alın","body":"Denemede kullanılan parça revizyonu, üretim malzemesi, bağlantı elemanları ve çalışma koşulları aynı kayıtta bulunmalıdır. Yük, temas edilen kimyasal veya sıcaklık değişirse eski kabulün yeni koşula aktarılabileceğini varsaymayın. Test sayısı ve kabul sınırı işletmenin ihtiyacına göre mühendislik sorumlusu tarafından belirlenir; genel bir çevrim sayısı bütün aparatlar için geçerli değildir."},{"title":"Koşullu onay ile seri onayını ayırın","body":"Numune küçük düzeltmelerle çalışıyorsa açık kalan maddeleri listeleyin. Revizyonun ardından hangi kontrollerin tekrar yapılacağını belirleyin. Onay kaydında dosya adı yerine parça kodu ve revizyon kullanın. Böylece tekrar sipariş ve bakım ihtiyacında hangi geometrinin üretileceği anlaşılır; sahada düzeltilmiş bir numune ile eski dijital dosya birbirine karışmaz."}]'::jsonb,'[{"q":"İlk numune onayından sonra aynı parçayı tekrar sipariş edebilir miyim?","a":"Onaylı dosya revizyonu ve üretim kapsamı korunarak tekrar talep hazırlanabilir. Kullanım koşulu değişmişse teknik değerlendirme yenilenmelidir."},{"q":"Kabul planı kalite sertifikası mıdır?","a":"Hayır. Projenin kabul koşullarını tanımlayan çalışma kaydıdır. Sertifika, kalibrasyon veya akredite ölçüm isteniyorsa bu ihtiyaç ayrıca kapsamlandırılır."},{"q":"Testte yapılan küçük düzeltmeler önemli mi?","a":"Evet. Zımpara, delik büyütme veya ek rondela gibi değişiklikler montajı etkilemiş olabilir. Tekrar üretimde aynı sonucu almak için dijital tasarıma işlenmelidir."}]'::jsonb,'{"answer":"Fikstür numunesi; parçayı doğru konumlandırma, bağlama, operatör erişimi ve tanımlanan çevrimde kullanım açısından kontrol edilmelidir. Kabul planı, her ölçütün nasıl deneneceğini ve kararı kimin vereceğini üretimden önce belirler. Yalnızca fotoğraf veya ilk montajın başarılı olması, tekrarlı kullanımın doğrulandığı anlamına gelmez.","takeaways":["Her kontrol maddesine yöntem ve sorumlu ekleyin.","İlk yerleşim ile tekrarlı kullanım denemesini ayrı kaydedin.","Sahada yapılan düzeltmeler onaylı CAD revizyonuna geri dönmeli."],"comparison":{"title":"Örnek kabul kontrol tablosu","columns":["Madde","Kontrol yöntemi","Kayıt"],"rows":[["Yerleşim","Referans iş parçasıyla montaj","Temas ve boşluk noktaları"],["Erişim","Operatörün gerçek hareketi","Engel ve iyileştirme listesi"],["Bağlama","Belirlenmiş bağlantılarla deneme","Gevşeme / kayma gözlemi"],["Revizyon","CAD ile numunenin karşılaştırılması","Onaylı dosya kodu"]]},"relatedPaths":["/3d-baski","/3d-modelleme","/rehber/aparat-malzeme-secimi","/cozumler/test-kontrol-aparatlari"]}'::jsonb FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT (tenant_id,path) DO NOTHING;

INSERT INTO public.landing_pages(tenant_id,path,title,summary,kind,image,status,sections,faq,editorial) SELECT id,'/rehber/aparat-malzeme-secimi','Montaj aparatı için malzeme nasıl seçilir?','Aparat malzemesini yalnızca sertlik veya filament adına göre seçmeyin; yük yönü, sıcaklık, kimyasal temas ve aşınmayı bir kullanım dosyasında toplayın.','guide','','draft','[{"title":"Çalışma koşulunu ölçülebilir tarif edin","body":"“Sağlam olsun” yerine aparatın taşıdığı yükü, yükün yönünü, temas süresini ve maruz kaldığı ortamı açıklayın. Sıcak yüzeye kısa süre dokunmak ile sürekli sıcak ortamda çalışmak farklı koşullardır. Temizlik ürünlerinin adı, yağ teması veya güneş altında kullanım bilgisi de seçime dâhil edilmelidir. Bilinmeyen koşulları tahmin ederek kesin malzeme seçimi yapmak yerine önce gerekli bilgiyi tamamlayın."},{"title":"Gövde ile temas yüzeyini ayrı düşünün","body":"İş parçasına dokunan yüzey, aparata ait taşıyıcı gövdeden farklı bir görev üstlenebilir. Çizilmeyi önleyen değiştirilebilir temas elemanı veya aşınan burç kullanımı tasarım görüşmesinde değerlendirilebilir. Bu yaklaşım her projede uygun değildir; ek parçanın montajı, bakım şekli ve tolerans ilişkisi de tasarlanmalıdır. Amaç malzeme değiştirmekten önce hangi bölgenin hangi görevi yaptığını anlamaktır."},{"title":"Üretim yönünü ve bağlantıları hesaba katın","body":"Katmanlı parçanın yükü hangi yönde aldığı önemlidir. Vida bağlantısı, insert, delik çevresi veya ince bir kol aynı malzemeden yapılmış kalın bir bloktan farklı davranabilir. Teknik talebe bağlantı noktalarını ve sıkma yöntemini ekleyin. Gerekli performansı yalnızca doluluk oranını artırarak elde edeceğinizi varsaymayın; geometri, duvarlar ve yön de değerlendirilmelidir."},{"title":"Malzeme değişirse onayı yenileyin","body":"Aynı tasarımın farklı filament ailesi veya farklı ürün sınıfıyla üretilmesi davranışı değiştirebilir. Onay kaydında yalnızca “plastik” yazmak yerine seçilen malzeme ve üretim revizyonunu belirtin. İşletme için kritik aparatta son kararı uygulamadan sorumlu mühendislik ekibi vermelidir. Genel malzeme tablosu, parçanın çalışacağı koşulda yapılan kabul testinin yerine geçmez."}]'::jsonb,'[{"q":"En sert malzeme en doğru seçim midir?","a":"Her zaman değil. Sertlik, darbe dayanımı, esneklik ve sıcaklık davranışı farklı özelliklerdir. Parçanın görevine uygun kombinasyon değerlendirilmelidir."},{"q":"Doluluğu artırmak sorunu çözer mi?","a":"Tek başına garanti etmez. Duvar düzeni, geometri, yük yönü ve bağlantı tasarımı birlikte değerlendirilmelidir."},{"q":"Malzeme önerisi için dosya gerekli mi?","a":"İlk görüşme kullanım açıklamasıyla başlayabilir. Geometriyi ve bağlantıları görmeden nihai üretim önerisi sınırlı kalır."}]'::jsonb,'{"answer":"Aparat malzemesi, çalışma koşulu ve parçanın görevine göre seçilir. Rijitlik, darbe davranışı, sıcaklık, kimyasal temas ve baskı yönü birlikte değerlendirilir. Malzeme ailesinin genel özellikleri bir başlangıçtır; son karar kullanılacak ürünün teknik verisi ve gerçek aparat denemesiyle desteklenmelidir.","takeaways":["Anlık en yüksek sıcaklık ile sürekli çalışma sıcaklığı farklıdır.","Yüzey aşınması gövde dayanımından ayrı bir ihtiyaçtır.","Baskı yönünü malzeme kararının dışında bırakmayın."],"comparison":{"title":"Malzeme seçimi için gerekli veriler","columns":["Etki","Sorulacak soru","Karara katkısı"],"rows":[["Yük","Nereden, hangi yönde uygulanıyor?","Geometri ve yön seçimi"],["Sıcaklık","Ne kadar süre maruz kalıyor?","Teknik veri değerlendirmesi"],["Kimyasal","Hangi maddeyle temas ediyor?","Uyumluluk incelemesi"],["Aşınma","Hangi yüzey tekrar temas ediyor?","Değiştirilebilir detay kararı"]]},"relatedPaths":["/3d-baski","/rehber/fikstur-numune-kabul-plani","/malzemeler/petg"]}'::jsonb FROM public.tenants WHERE slug='3dsanayi' ON CONFLICT (tenant_id,path) DO NOTHING;

INSERT INTO public.landing_pages(tenant_id,path,title,summary,kind,image,status,sections,faq,editorial) SELECT id,'/rehber/mimari-maket-olcek-secimi','Mimari maket ölçeği nasıl seçilir?','1:50, 1:100 veya 1:200 kararını sunum alanı, anlatılacak detay ve taşıma boyutuyla birlikte verin. Ölçek hesabını bir yerleşim örneğiyle inceleyin.','guide','','draft','[{"title":"Taban alanından geriye doğru hesaplayın","body":"Sunum masası veya vitrin için ayrılan net alanı ölçün. Bina ve çevre düzeninin birlikte kaplayacağı gerçek sınırı belirleyin. Örneğin 60 metrelik bir yerleşim 1:100 ölçekte 60 santimetreye, 1:200 ölçekte 30 santimetreye karşılık gelir. Kenar payı, etiketler ve koruyucu kapak bu hesabın dışında değildir; son taban ölçüsüne eklenmelidir."},{"title":"Detay bütçesini belirleyin","body":"Ölçek küçüldüğünde cephe, korkuluk ve peyzaj ayrıntılarının maketteki karşılığı da küçülür. Bu elemanların hepsini gerçek ölçülerini koruyarak üretmek mümkün veya yararlı olmayabilir. Hangi ayrıntının anlatımı taşıdığını seçin. Örneğin kütle ilişkisini gösteren bir çalışmada malzeme deseni yerine açıklıkların oranı daha önemli olabilir. Küçük bir temsil parçası, bütün modeli hazırlamadan karar vermeyi kolaylaştırır."},{"title":"Katları ve kesiti sunum biçimine bağlayın","body":"İç mekân anlatılacaksa yalnızca dış kabuğun ölçeği yeterli değildir. Katları ayırmak, bir cepheyi kaldırmak veya kesit yüzeyi oluşturmak gerekebilir. Bu kararlar birleşim noktalarını ve taşıyıcı geometriyi etkiler. Sunum sırasında kimin hangi parçayı açıp kapatacağını düşünerek modül ağırlığı, kavrama ve saklama düzenini planlayın."},{"title":"Taşıma ve yeniden kurulum ölçüsünü kontrol edin","body":"Maketin tamamlanmış tabanı kapı, araç ve taşıma kutusuna sığmalıdır. Büyük yerleşimi modüllere ayırırken birleşimleri doğal proje sınırlarına yerleştirmek görsel bütünlüğü korumaya yardımcı olabilir. Birleştirme sırası ve modül etiketleri dijital dosyayla birlikte hazırlanırsa tekrar kurulum daha kontrollü yapılır. Son teklif; bina, çevre, kaide ve taşıma kapsamını ayrı göstermelidir."}]'::jsonb,'[{"q":"En büyük ölçek her zaman daha iyi mi?","a":"Hayır. Sunum amacı, izleme mesafesi ve sergileme alanı belirleyicidir. Büyük maket daha fazla detay gösterebilir ancak taşıma ve kurulum kapsamını da artırabilir."},{"q":"Projem farklı bir ölçekte hazırlanmışsa ne olur?","a":"Dijital dosyanın birimi ve gerçek ölçüsü doğrulanarak hedef maket ölçeğine hazırlanabilir. Yalnızca ölçek katsayısını değiştirmek, ince detayların üretilebilirliğini çözmez."},{"q":"Çevre düzeni fiyatın içinde midir?","a":"Kapsama göre değişir. Peyzaj, komşu kütleler, yollar, taban ve etiketler teklif dosyasında ayrı tanımlanmalıdır."}]'::jsonb,'{"answer":"Maket ölçeği, gerçek ölçünün seçilen ölçek paydasına bölünmesiyle hesaplanır. Örneğin 30 metre uzunluğundaki bina 1:100 ölçekte 30 santimetre olur. Doğru seçim; maketin sığacağı alan, okunması gereken detaylar ve taşıma planına bağlıdır. Çevre düzeni ve kaide için ayrıca yer ayrılmalıdır.","takeaways":["Ölçek hesabından önce bütün ölçüleri aynı birime çevirin.","Bina boyutu ile maketin taban boyutu aynı değildir.","İnce detayların fiziksel ölçekte okunabilirliğini test edin."],"comparison":{"title":"30 metre uzunluğundaki bina için ölçek hesabı","columns":["Ölçek","Maket uzunluğu","Değerlendirme odağı"],"rows":[["1:50","60 cm","Daha ayrıntılı bina anlatımı"],["1:100","30 cm","Bina ve yakın çevre dengesi"],["1:200","15 cm","Kütle ve yerleşim ilişkisi"]]},"relatedPaths":["/3d-baski","/3d-modelleme","/rehber/maket-fiyati-teklif-kapsami","/cozumler/arazi-yerlesim-modelleri"]}'::jsonb FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT (tenant_id,path) DO NOTHING;

INSERT INTO public.landing_pages(tenant_id,path,title,summary,kind,image,status,sections,faq,editorial) SELECT id,'/rehber/maket-fiyati-teklif-kapsami','Mimari maket fiyatı için hangi bilgiler gerekir?','Maket teklifini ölçek, model hazırlığı, çevre düzeni, yüzey bitişi ve teslim kapsamıyla netleştirin; son dakika revizyonlarını başlangıçta planlayın.','guide','','draft','[{"title":"Dosyanın durumunu doğru tarif edin","body":"Elinizdeki modelin programını ve son revizyonunu paylaşın. Yalnızca görüntü almak için hazırlanmış modelde ince yüzeyler, açık geometri veya fiziksel üretim için gereksiz detaylar bulunabilir. Baskıya hazırlık ile sıfırdan modelleme farklı çalışmalardır. Dosya incelenmeden bu iki kalemin aynı kabul edilmesi teklif karşılaştırmasını yanıltır."},{"title":"Görsel bitişi örneklerle belirleyin","body":"Tek renk kütle maketi, malzeme ayrımı yapılan sunum maketi ve boyanmış detaylı maket farklı işçilik ister. İstenen renklerin hangi bölgelerde olacağını ve birleşimlerin ne ölçüde görünür olabileceğini belirtin. Referans görsel kullanıyorsanız hoşunuza giden özelliği yazın: yüzey, ölçek, renk veya çevre düzeni. Böylece görsel beklenti somut bir üretim kararına dönüşür."},{"title":"Revizyon sınırlarını sunum takvimine bağlayın","body":"Mimari proje üretim sırasında değişebilir. Hangi tarihte hangi modüllerin onaya bağlanacağını belirlemek, bütün maketin tekrar yapılmasını gerektirebilecek değişiklikleri erkenden fark ettirir. Baskıya geçildikten sonra değişen cephe veya kütleyi ayrı revizyon olarak paylaşın. Hedef sunum tarihi tek başına üretim süresini tanımlamaz; dosya onayı ve son işlem için de zaman gerekir."},{"title":"Teslimin fiziksel kapsamını yazın","body":"Maketle birlikte taban, şeffaf kapak, etiket, taşıma kutusu veya sahada kurulum istenip istenmediğini netleştirin. Açılır katların ve küçük ayrılabilir parçaların saklanacağı düzen de teslimin parçası olabilir. Uzak bir sunum için paketleme biçimini baştan konuşun. Teklifte bu kalemlerin yer alması, son aşamada eksik görünen hizmetleri ve beklenmedik maliyetleri azaltır."}]'::jsonb,'[{"q":"Sadece proje görseliyle kesin teklif çıkar mı?","a":"İlk kapsam konuşulabilir; geometri, ölçek ve detayların incelenmesi kesin üretim teklifi için gereklidir."},{"q":"Maketin bütün parçaları 3D baskı mı olmalı?","a":"Sunum hedefi ve tasarıma göre farklı malzeme veya yapım yöntemleri değerlendirilebilir. Teklifte her parçanın üretim ve montaj kapsamı açıklanmalıdır."},{"q":"Revizyon gelirse ne olur?","a":"Değişen model ve üretime geçmiş modüller karşılaştırılır. Etkilenen parçaların hazırlık, baskı ve son işlem kapsamı yeniden değerlendirilir."}]'::jsonb,'{"answer":"Mimari maket fiyatını hedef ölçek, toplam taban ölçüsü, modelin hazırlık durumu, detay seviyesi, boyama, montaj ve taşıma kapsamı belirler. Aynı projeye verilen fiyatları karşılaştırmak için yalnızca bina görseli yeterli değildir. Hangi çevre elemanlarının, açılır katların ve teslim parçalarının dâhil olduğu yazılmalıdır.","takeaways":["Mimari tasarım dosyası her zaman baskıya hazır dosya değildir.","Kaide, kapak ve taşıma kutusunu teklif kapsamına açıkça ekleyin.","Sunum tarihi ile üretime onay verilecek tarihi ayrı planlayın."],"comparison":{"title":"Teklif kapsamı kontrol listesi","columns":["Başlık","Paylaşılacak bilgi","Netleşecek karar"],"rows":[["Ölçek","Bina ve taban ölçüsü","Son fiziksel boyut"],["Model","Dosya ve revizyon","Hazırlık / modelleme işi"],["Bitiş","Renk ve yüzey referansı","Baskı sonrası işçilik"],["Teslim","Yer, tarih ve taşıma","Kutu, kurulum ve paketleme"]]},"relatedPaths":["/3d-modelleme","/rehber/mimari-maket-olcek-secimi","/cozumler/gayrimenkul-sunum-maketleri"]}'::jsonb FROM public.tenants WHERE slug='maketyanimda' ON CONFLICT (tenant_id,path) DO NOTHING;

INSERT INTO public.landing_pages(tenant_id,path,title,summary,kind,image,status,sections,faq,editorial) SELECT id,'/rehber/kirik-parca-yeniden-uretim','Kırık plastik parça yeniden nasıl üretilir?','Numune, montaj yeri ve kritik ölçülerden başlayarak tarama, modelleme ve ilk uyum denemesini planlayın. Eksik geometriyi doğru referansla tamamlayın.','guide','','draft','[{"title":"İlk değerlendirme için fotoğraf seti hazırlayın","body":"Parçayı ön, arka ve yan yüzleri görünecek şekilde çekin. Boyutu anlatmak için bir cetvel veya bilinen ölçü ekleyin. Ayrı fotoğrafta montaj yuvasını, vida deliklerini ve eşleşen parçayı gösterin. Fotoğraftaki perspektif ölçüm belirsizliği yarattığı için yalnızca görsel üzerinden kesin geometri kurulacağını varsaymayın. Kritik mesafeleri ayrıca ölçerek belirtin."},{"title":"Eksik alanın kaynağını belirleyin","body":"Kırılan tırnak veya kaybolan köşe için sağlam bir örnek bulunuyorsa onu da paylaşın. Karşı taraftaki parçayı referans almak mümkün olabilir, ancak sağ ve sol parçaların tam simetrik olduğu ölçülmeden kabul edilmemelidir. Aşınmış yüzeyin eski nominal ölçüsünü anlamak için montaj yuvası veya teknik çizim gerekebilir. Tasarım yorumuyla tamamlanan bölgeler numunede özellikle kontrol edilmelidir."},{"title":"Malzemeyi görünüşe göre seçmeyin","body":"Orijinal parçanın rengi ve sert hissedilmesi malzeme özelliklerini kesin olarak göstermez. Parçanın bulunduğu ortamı, güneş ve sıcaklık etkisini, esneme ihtiyacını ve bağlantı şeklini anlatın. Araç veya makinede güvenlik açısından kritik işlevler, dekoratif kapakla aynı süreçte değerlendirilmez. Gerekli teknik doğrulama kapsamı üretim kararı verilmeden belirlenmelidir."},{"title":"İlk uyumdan sonra dosyayı sabitleyin","body":"Numuneyi montaj yerinde deneyin. Hangi noktada sıkıştığını, ne kadar boşluk kaldığını ve parçanın sökülüp takılabildiğini kaydedin. Yapılan değişiklikleri yeni dosya revizyonuna aktarın. Çoklu sipariş için onaylanan örneği ve dijital dosyayı eşleştirin. Farklı model yılı veya cihaz revizyonunda aynı uyumun geçerli olduğunu varsaymayın."}]'::jsonb,'[{"q":"Kırık tırnak taramayla geri gelir mi?","a":"Hayır. Tarama mevcut yüzeyi kaydeder. Eksik tırnak için referans ölçü veya tasarım çalışması gerekir."},{"q":"Her otomotiv parçası basılabilir mi?","a":"Her parçanın kullanım görevi farklıdır. Güvenlik, sıcaklık, yük ve mevzuat gereksinimleri teknik uygunluğu belirler; genel bir basılabilirlik vaadi verilemez."},{"q":"Orijinal parçadan daha dayanıklı yapılabilir mi?","a":"Geometri veya malzeme değişikliği değerlendirilebilir; daha yüksek performans ancak tanımlı koşullarda doğrulamayla gösterilebilir. Kalınlaştırma tek başına yeterli değildir."}]'::jsonb,'{"answer":"Kırık plastik parçanın yeniden üretimi; işlevin anlaşılması, mevcut geometrinin ölçülmesi, eksik bölgelerin modellenmesi ve numune uyumunun denenmesiyle ilerler. Tarama yalnızca erişilebilir yüzeyleri verir; kaybolan ayrıntıları kendiliğinden oluşturmaz. Montaj yuvası, sağlam karşılık veya ölçülü çizim çoğu zaman en değerli ek referanstır.","takeaways":["Kırık parçayı atmayın; küçük parçacıkları da saklayın.","Parçanın oturduğu yeri ve bağlantıları fotoğraflayın.","Bir parçayı yeniden üretmenin teknik uygunluğunu kullanım görevi belirler."],"comparison":{"title":"Elinizde ne varsa süreç nereden başlar?","columns":["Mevcut referans","İlk adım","Ek ihtiyaç"],"rows":[["Sağlam parça","Ölçüm / tarama","Kullanım koşulu"],["Kırık parça","Hasar ve eksik alan incelemesi","Karşı parça veya ölçü"],["Sadece fotoğraf","Kapsam değerlendirmesi","Gerçek ölçüler"],["CAD dosyası","Revizyon ve üretilebilirlik kontrolü","Malzeme ve montaj bilgisi"]]},"relatedPaths":["/3d-tarama","/3d-modelleme","/3d-baski","/rehber/otomotiv-plastik-parca-malzeme"]}'::jsonb FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT (tenant_id,path) DO NOTHING;

INSERT INTO public.landing_pages(tenant_id,path,title,summary,kind,image,status,sections,faq,editorial) SELECT id,'/rehber/otomotiv-plastik-parca-malzeme','Otomotiv plastik parçasında malzeme seçimi','Trim, kapak ve adaptörlerde güneş, kabin sıcaklığı, esneyen bağlantılar ve yüzey beklentisini birlikte değerlendirin; malzeme adını uygunluk garantisi saymayın.','guide','','draft','[{"title":"Montaj yerini doğru tanımlayın","body":"Parçanın araç içinde nerede durduğunu fotoğraflayın. Cam arkasındaki güneş etkisi, dış ortamda yağmur ve UV etkisi veya sıcak bir bileşene yakınlık farklı değerlendirmeler doğurur. Sıcaklık bilinmiyorsa yaklaşık bir sayı uydurmak yerine ölçüm veya üretici verisi ihtiyacını belirleyin. Malzeme seçimi yalnızca aracın markası ve modeli üzerinden yapılmaz."},{"title":"Bağlantının nasıl çalıştığını anlatın","body":"Bazı kapaklar vidalanır, bazıları tırnakla tutunur, bazı adaptörler ise karşı parçaya geçer. Esneyen tırnağın uzunluğu ve kalınlığı, baskı yönü ve seçilen polimerle birlikte değerlendirilmelidir. Daha rijit bir malzeme bağlantıyı kolaylaştırmak yerine zorlayabilir. Sökme-takma ihtiyacını ve montajda kullanılan kuvvetin nereden uygulandığını paylaşın."},{"title":"Teknik veri ile uygulama denemesini birleştirin","body":"Filament ailesinin genel bilgisi ön eleme için yararlıdır. Belirli ürünün üretici teknik föyünü incelemek ve parçanın koşullarını bu veriyle karşılaştırmak gerekir. Baskı sonrası işlem, nem ve üretim parametreleri de sonucu etkileyebilir. Genel bir internet tablosundan alınan değeri üretilmiş parçanın garantili performansı gibi kullanmayın."},{"title":"Görünüş ve işlev için ayrı onay verin","body":"Renk, doku ve katman izleri görsel onayın konusudur. Montaj uyumu, esneme ve ortam koşulunda davranış ise işlev onayının konusudur. Bu iki onayı ayrı kaydetmek, fotoğrafta beğenilen parçanın teknik olarak da kabul edildiği varsayımını önler. Nihai karar, kullanımın gerektirdiği mühendislik değerlendirmesiyle birlikte verilmelidir."}]'::jsonb,'[{"q":"PLA, PETG veya ASA arasında doğrudan seçim yapabilir miyim?","a":"Önce çalışma koşulu tanımlanmalıdır. Polimer ailesi genel bir başlangıç verir; belirli ürünün verisi, geometri ve üretim yönü nihai seçimi etkiler."},{"q":"Aynı rengi bulmak teknik eşdeğerlik sağlar mı?","a":"Hayır. Renk eşleşmesi ile malzeme davranışı ayrı konulardır. Görsel ve işlevsel gereksinimler ayrı kontrol edilir."},{"q":"Bir numune bütün kullanımları doğrular mı?","a":"Yalnızca tanımlanmış ve denenmiş koşullar hakkında bilgi verir. Farklı araç revizyonu veya çalışma ortamı yeni değerlendirme gerektirebilir."}]'::jsonb,'{"answer":"Otomotiv için özel plastik parçanın malzemesi; montaj yeri, sıcaklık, UV maruziyeti, kimyasal temas ve mekanik göreve göre değerlendirilir. Görsel kabin detayı ile yük taşıyan veya güvenlikle ilgili parça aynı gereksinimlere sahip değildir. Malzeme seçimi, kullanılacak ürünün teknik verisi ve numune denemesiyle yapılmalıdır.","takeaways":["Kabin, dış yüzey ve motor çevresi farklı ortam koşullarıdır.","Sökülüp takılan tırnaklarda geometri ve esneme birlikte değerlendirilir.","“Otomotive uygun” ifadesi tek başına teknik kabul kriteri değildir."],"comparison":{"title":"Parça konumuna göre sorulacak sorular","columns":["Konum / görev","Öncelikli bilgi","Değerlendirme"],"rows":[["Kabin detayı","Güneş, sıcaklık ve yüzey beklentisi","Görsel ve ortam denemesi"],["Dış kapak","UV, su ve bağlantı şekli","Ürün teknik verisi ve montaj"],["Esnek bağlantı","Hareket ve sökme sıklığı","Geometri ve esneme testi"],["Kritik uygulama","Güvenlik ve işlev gereksinimi","Yetkili mühendislik doğrulaması"]]},"relatedPaths":["/rehber/kirik-parca-yeniden-uretim","/3d-baski","/cozumler/ic-trim-kapaklar"]}'::jsonb FROM public.tenants WHERE slug='parcayanimda' ON CONFLICT (tenant_id,path) DO NOTHING;
